def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    person_patches = image_patch.find("person")
    sweatshirt_patches = image_patch.find("sweatshirt")

    if not person_patches or not sweatshirt_patches:
        return image_patch

    gray_sweatshirts = [s for s in sweatshirt_patches if s.verify_property("sweatshirt", "gray")]

    if not gray_sweatshirts:
        return image_patch

    gray_sweatshirt_persons = []
    for person in person_patches:
        person_rect = (person.left, person.lower, person.right, person.upper)
        for sweatshirt in gray_sweatshirts:
            sweatshirt_rect = (sweatshirt.left, sweatshirt.lower, sweatshirt.right, sweatshirt.upper)
            if person.overlaps_with(*sweatshirt_rect):
                gray_sweatshirt_persons.append(person)
                break

    if not gray_sweatshirt_persons:
        return image_patch

    gray_sweatshirt_persons.sort(key=lambda p: p.horizontal_center)
    return gray_sweatshirt_persons[-1]

