modern_c5_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    giraffes = image_patch.find("giraffe")
    if len(giraffes) < 2: 
        return image_patch

    # Find pairs of giraffes where one is licking the other
    licking_pairs = []
    for i in range(len(giraffes)):
        for j in range(i + 1, len(giraffes)):
            if is_in_front_of(giraffes[i], giraffes[j]):
                licking_pairs.append((giraffes[i], giraffes[j]))

    # Sort pairs by the depth of the first giraffe in the pair
    licking_pairs.sort(key=lambda x: x[0].compute_depth())

    # Select the pair with the closest first giraffe
    if licking_pairs:
        return licking_pairs[0][0]

    return image_patch

