    image_patch = ImagePatch(image)
    dogs = image_patch.find("dog")
    sofas = image_patch.find("sofa")

    if not dogs or not sofas:
        return image_patch

    black_dog = [d for d in dogs if d.verify_property("dog", "black")]
    if not black_dog:
        return image_patch

    black_dog = black_dog[0]

    sofa_patches = []
