    giraffes = image_patch.find("giraffe")

    if len(giraffes) < 2:
        return image_patch

    big_giraffe = max(giraffes, key=lambda g: g.width * g.height)
    small_giraffes = [g for g in giraffes if g != big_giraffe]

    if not small_giraffes:
        return big_giraffe

    small_giraffe = min(small_giraffes, key=lambda s: s.width * s.height)

    if abs(big_giraffe.horizontal_center - small_giraffe.horizontal_center) < abs(big_giraffe.vertical_center - small_giraffe.vertical_center):
        return big_giraffe if big_giraffe.horizontal_center < small_giraffe.horizontal_center else small_giraffe
    else:
        return big_giraffe if big_giraffe.vertical_center < small_giraffe.vertical_center else small_giraffe

