def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    couch_patches = image_patch.find("couch")
    floor_patches = image_patch.find("floor")
    wall_patches = image_patch.find("wall")
    window_patches = image_patch.find("window")

    if not couch_patches:
        return image_patch

    # Filter walls without windows
    valid_wall_patches = [wall for wall in wall_patches if not any(window.overlaps_with(wall.left, wall.lower, wall.right, wall.upper) for window in window_patches)]

    if not valid_wall_patches:
        return couch_patches[0]

    # Find the couch in front of a wall
    for couch in couch_patches:
        for wall in valid_wall_patches:
            if couch.overlaps_with(wall.left, wall.lower, wall.right, wall.upper):
                return couch

    # If no specific position found, return the first couch found
    return couch_patches[0]

